class Stack(list):
    def push(self, item):
        self.append(item)

    def pop(self):
        if not self:
            raise IndexError('pop from empty stack')
        return super().pop()


class CorrectBracketingChecker:
    def __init__(self):
        self.stack = Stack()

    def check(self, bracket):
        if bracket == '<':
            self.stack.push(bracket)
        elif bracket == '>':
            if not self.stack:
                return False
            self.stack.pop()
        return True

    def is_correct(self, brackets):
        for bracket in brackets:
            if not self.check(bracket):
                return False
